const bootStarted=performance.now();
let world,engine,ui;
const keys=new Set(),stick={x:0,z:0};let soundOn=false,cinematics=true,audio=null,visibilityPaused=document.hidden,saveElapsed=0;
function hasSave(mode){try{return !!localStorage.getItem(`chibi-world-v1-${mode}`);}catch{return false;}}
function tutorialSeen(){try{return localStorage.getItem('jujutsu-tutorial-v2')==='done';}catch{return false;}}
function finishTutorial(){try{localStorage.setItem('jujutsu-tutorial-v2','done');}catch{}}
function readMode(){try{return localStorage.getItem('chibi-world-mode')||'sandbox';}catch{return 'sandbox';}}
function readSave(mode){try{return restoreState(JSON.parse(localStorage.getItem(`chibi-world-v1-${mode}`)),mode);}catch{return createState(mode);}}
function save(){try{localStorage.setItem(`chibi-world-v1-${engine.s.mode}`,JSON.stringify(serializable(engine.s)));localStorage.setItem('chibi-world-mode',engine.s.mode);}catch{ui?.toast('Browser storage is unavailable. Export your save in Settings.',true);}}
function sound(note=440){if(!soundOn)return;try{audio||=new AudioContext();audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.setValueAtTime(note,audio.currentTime);gain.gain.setValueAtTime(.025,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.3);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.31);}catch{}}
const heroVisuals=new Map(),loot=[],summons=[],pets=[];
function animatePet(p,t,kind){const frame=Math.floor(t*10)%8,key=kind+frame;if(key===p.lastFrame)return;p.lastFrame=key;const canvas=p.m.material.map.image,ctx=canvas.getContext('2d');ctx.clearRect(0,0,128,128);ctx.drawImage(companionCanvas(p.id,frame,kind),0,0);p.m.material.map.needsUpdate=true;}
function petCanvas(id){return companionCanvas(id);}
function petSprite(id,x,z,scale=1.3){const tex=new T.CanvasTexture(petCanvas(id));tex.colorSpace=T.SRGBColorSpace;const m=new T.Sprite(new T.SpriteMaterial({map:tex,transparent:true,depthWrite:false}));m.center.set(.5,.1);m.scale.setScalar(scale);m.position.set(x,.25,z);world.actors.add(m);return m;}
function rebuildRegion(){clearInput();cinema?.stop();world.build(engine.s.region,engine.s);for(const p of pets){world.actors.remove(p.m);p.m.material.map.dispose();p.m.material.dispose();}pets.length=0;if(engine.s.region==='forest'){for(const p of [{id:'panda',x:-4,z:7},{id:'dog',x:2,z:5}])pets.push({...p,m:petSprite(p.id,p.x,p.z),hop:0});}for(const l of loot)world.fx.remove(l.m);loot.length=0;for(const summon of summons){world.actors.remove(summon.m);summon.m.material.map.dispose();summon.m.material.dispose();}summons.length=0;}

const cinema=new Cinematics();
function showCinematic(data){if(!cinematics||data.hero!==engine.s.controlled)return;cinema.start(data,engine.s.enemies.find(e=>e.isBoss)||engine.s.enemies[0]);}

function event(type,data){if(type==='cinematic')showCinematic(data);if(type==='ultimateRelease')cinema.release(data.hero);if(type==='questComplete')sound(880);if(type==='toast')ui?.toast(data.text,data.warn);if(type==='hostileShot')data.visual=world.effect('orb',data.x,data.z,'#d9a7df',.25,3);if(type==='effect')world.effect(data.type,data.x,data.z,data.color,data.size,data.duration,data.dx,data.dz);if(type==='float')world.floating(data.text,data.x,data.z,data.color);if(type==='region')rebuildRegion();if(type==='save')save();if(type==='party')ui?.renderParty();if(type==='sound')sound(data.note);if(type==='spawnEnemy')data.visual=world.createEnemy(data);if(type==='removeEnemy')world.removeEnemy(data);if(type==='boop'){const p=pets.find(p=>p.id===data.id);if(p)p.hop=.35;world.floating('♡',data.x,data.z,'#e8a7b2');}if(type==='summon'){const m=petSprite(data.id,data.x,data.z,data.id==='rika'?3:1.7);summons.push({...data,m});}if(type==='loot'){for(let i=0;i<data.n;i++){const m=new T.Mesh(data.key==='crystal'?new T.OctahedronGeometry(.13):new T.BoxGeometry(.2,.16,.3),mat(data.key==='wood'?'#b8926f':data.key==='crystal'?'#9fdae8':'#b6d88c'));m.position.set(data.x,.6,data.z);world.fx.add(m);loot.push({m,vx:(Math.random()-.5)*3,vz:(Math.random()-.5)*3,vy:4,bounces:0,life:0});}}}
function changeMode(mode){save();for(const e of engine.s.enemies)world.removeEnemy(e);engine.s=readSave(mode);rebuildRegion();ui.renderParty();ui.toast(mode==='survival'?'Survival · earn your path, together.':'Sandbox · the whole world is yours.');save();}
function clearInput(){keys.clear();stick.x=stick.z=0;const knob=document.querySelector('#joystick i');if(knob)knob.style.transform='';}
function aimTouch(){if(!matchMedia('(pointer:coarse)').matches)return;const p=engine.player,e=engine.s.enemies.filter(e=>dist(e,p)<10).sort((a,b)=>dist(a,p)-dist(b,p))[0];if(e){const d=dist(e,p);p.facing={x:(e.x-p.x)/Math.max(.01,d),z:(e.z-p.z)/Math.max(.01,d)};}}
try{
 await loadCharacterArt(progress=>{const percent=Math.round(progress*100);$('loading-progress').style.width=percent+'%';$('loading-percent').textContent=percent+'%';document.querySelector('.loading-track').setAttribute('aria-valuenow',String(percent));});world=new World($('world'));engine=new Engine(readSave(readMode()),event,(x,z)=>world.canMove(x,z));for(const h of HEROES)heroVisuals.set(h.id,world.createHero(h.id));rebuildRegion();ui=new UI(engine,world,{save,saveData:()=>serializable(engine.s),changeMode,hasSave,tutorialSeen,finishTutorial,startMode:mode=>{changeMode(mode);clearInput();},cinematicsEnabled:()=>cinematics,toggleCinematics:()=>{cinematics=!cinematics;},soundEnabled:()=>soundOn,toggleSound:()=>{soundOn=!soundOn;sound(500);},clearInput});const originalAction=engine.action.bind(engine);engine.action=action=>{if(action.startsWith('ability')||action==='interact')aimTouch();originalAction(action);};
 const mapped={KeyE:'interact',Space:'interact',ShiftLeft:'dash',ShiftRight:'dash',Digit1:'ability0',Digit2:'ability1',Digit3:'ability2',KeyR:'special',KeyX:'sit',KeyV:'gear',KeyQ:'infinity'};
 document.addEventListener('keydown',e=>{if(e.code==='Escape'){ui.close();return;}if(['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space','Tab'].includes(e.code)&&!ui.opened)e.preventDefault();if(e.code==='Escape'){ui.close();return;}if(e.repeat)return;if(!ui.opened){if(e.code==='KeyM')ui.map();else if(e.code==='KeyP')ui.party();else if(e.code==='KeyJ')ui.journal();else if(e.code==='KeyB')ui.studio();else if(['KeyZ','KeyC','KeyF'].includes(e.code))engine.switchHero(engine.s.party[['KeyZ','KeyC','KeyF'].indexOf(e.code)]);else if(mapped[e.code])engine.action(mapped[e.code]);}keys.add(e.code);});document.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',clearInput);document.addEventListener('visibilitychange',()=>{visibilityPaused=document.hidden;clearInput();if(document.hidden)save();});window.addEventListener('pagehide',save);
 const joy=$('joystick'),knob=joy.querySelector('i');let joyPointer=null;const joyMove=e=>{const r=joy.getBoundingClientRect(),x=e.clientX-(r.left+r.width/2),y=e.clientY-(r.top+r.height/2),d=Math.max(1,Math.hypot(x,y)/34);stick.x=x/d/34;stick.z=y/d/34;knob.style.transform=`translate(${x/d}px,${y/d}px)`;};joy.onpointerdown=e=>{e.preventDefault();joyPointer=e.pointerId;joy.setPointerCapture(e.pointerId);joyMove(e);};joy.onpointermove=e=>{if(e.pointerId===joyPointer)joyMove(e);};const joyEnd=e=>{if(e.pointerId===joyPointer){joyPointer=null;stick.x=stick.z=0;knob.style.transform='';}};joy.onpointerup=joyEnd;joy.onpointercancel=joyEnd;
 world.renderer.domElement.addEventListener('pointerdown',e=>{if(ui.opened||e.pointerType==='touch')return;const point=world.screenToWorld(e.clientX,e.clientY);const p=engine.player,d=Math.hypot(point.x-p.x,point.z-p.z);if(d>.01)p.facing={x:(point.x-p.x)/d,z:(point.z-p.z)/d};engine.action('interact');});
 let last=performance.now(),acc=0,t=0,hudAcc=0,renderAcc=0;function loop(now){let dt=Math.min((now-last)/1000,.1);last=now;if(!ui.opened&&!visibilityPaused){acc+=dt;while(acc>=1/60){let x=stick.x+(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),z=stick.z+(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0);engine.update(1/60,{x,z});acc-=1/60;}t+=dt;saveElapsed+=dt;if(saveElapsed>8){save();saveElapsed=0;}}
 for(const h of HEROES){const v=heroVisuals.get(h.id),a=engine.s.heroes[h.id];if(engine.s.party.includes(h.id)){v.group.visible=true;world.updateHero(v,a,t,h.id===engine.s.controlled);}else if(engine.s.region==='school'){const pos=engine.npcPositions[h.id];v.group.visible=!!pos;if(pos)world.updateHero(v,{...a,...pos,moving:false,sitting:false,animTime:0,facing:{x:0,z:1}},t,false);}else v.group.visible=false;}
 for(const e of engine.s.enemies)if(e.visual)world.updateEnemy(e,t);for(const p of pets){animatePet(p,t,p.hop>0?'attack':'idle');if(p.hop>0&&!ui.opened)p.hop-=dt;p.m.position.y=.25+(p.hop>0?.6*Math.sin(Math.PI*(.35-p.hop)/.35):Math.sin(t*2)*.025);}
 if(!ui.opened&&!visibilityPaused){for(let i=loot.length-1;i>=0;i--){const l=loot[i];l.life+=dt;l.vy-=24*dt;l.m.position.x+=l.vx*dt;l.m.position.z+=l.vz*dt;l.m.position.y+=l.vy*dt;if(l.m.position.y<.3){l.m.position.y=.3;l.vy=Math.abs(l.vy)*.45;l.bounces++;}if(l.bounces>=2||l.life>1){l.m.position.lerp(new T.Vector3(engine.player.x,.7,engine.player.z),dt*7);}if(l.life>2||l.life>.8&&Math.hypot(l.m.position.x-engine.player.x,l.m.position.z-engine.player.z)<.3){world.fx.remove(l.m);l.m.geometry.dispose();loot.splice(i,1);}}for(let i=summons.length-1;i>=0;i--){const s=summons[i];animatePet(s,t,'attack');s.life-=dt;s.m.position.y=.5+Math.sin(t*4)*.2;if(s.life<=0){world.actors.remove(s.m);s.m.material.map.dispose();s.m.material.dispose();summons.splice(i,1);}}}
 cinema.tick(ui.opened||visibilityPaused?0:dt);const p=engine.player;renderAcc+=dt;if((!ui.opened&&!visibilityPaused&&renderAcc>=1/30)||world.needsRender){world.tick(ui.opened||visibilityPaused?0:Math.min(renderAcc,.1),t,p,engine.night||engine.s.region==='domain'||engine.s.region==='shibuya');renderAcc=0;world.needsRender=false;}hudAcc+=dt;if(hudAcc>.1){ui.update();hudAcc=0;}requestAnimationFrame(loop);}
 ui.update();ui.onboarding();requestAnimationFrame(loop);setTimeout(()=>{$('loading').style.opacity=0;setTimeout(()=>$('loading').remove(),450);},Math.max(0,1800-(performance.now()-bootStarted)));window.chibi={engine,world,ui,save,serializable,cinema};
}catch(error){console.error(error);$('loading')?.remove();const fatal=document.createElement('div');fatal.id='fatal';fatal.innerHTML='<h1>The gates need a little help.</h1><p>Please reload in an up-to-date Chrome, Safari, or Firefox. The pixel world and characters use Canvas 2D.</p><button class="primary" onclick="location.reload()">Try again</button>';document.body.append(fatal);}
